class NeuCodecAudioProcessorKwargs(AudioKwargs, total=False):
    r"""
    hop_length (`int`, *optional*, defaults to 320):
        Codec frame size, in samples. Distinct from the STFT hop in `spectrogram_config`.
    stride (`int`, *optional*, defaults to 2):
        Number of mel frames stacked into each output frame.
    feature_padding_value (`float`, *optional*, defaults to 1.0):
        Value used to pad the extracted features.
    """

    hop_length: int
    stride: int
    feature_padding_value: float | int


class NeuCodecAudioProcessorMixin:
    """Same dual-encoder geometry as XCodec2: raw padded audio for the acoustic encoder, kaldi
    povey fbank features for the semantic one."""

    # Acoustic waveforms and semantic fbank features are assembled together by `_preprocess`.
    legacy_field_mapping = {
        "feature_size": None,
        "frame_length": None,
        "frame_shift": None,
        "num_mel_bins": None,
        "hop_length": None,
        "padding_value": "feature_padding_value",
    }
    model_input_names = ["audio_features", "audio_features_mask", "audio_values", "audio_values_mask"]
    pad_to_multiple_of = 320
    sampling_rate = 16000
    spectrogram_config = {
        "stft_config": {
            "n_fft": 512,
            "win_length": 400,
            "hop_length": 160,
            "window_fn": "povey",
            "power": 2.0,
            "center": False,
            "periodic": False,
            "left_align_fft": True,
        },
        "mel_scale_config": {
            "n_mels": 80,
            "f_min": 20.0,
            "f_max": 8000.0,
            "mel_scale": "kaldi",
            "triangularize_in_mel_space": True,
        },
        "log_mode": "log",
        "preemphasis": 0.97,
        "remove_dc_offset": True,
        "mel_floor": 1.192092955078125e-07,
        "waveform_scale": 32768.0,
        "transpose_features": True,  # kaldi's (time, n_mels) orientation
    }

    hop_length = 320
    stride = 2
    feature_padding_value = 1.0
    valid_kwargs = NeuCodecAudioProcessorKwargs

    def _prepare_waveform(self, audio_el, **kwargs):
        # the legacy FE appends one zero sample to every waveform before padding
        return self._pad_axis(audio_el, 0, 1, axis=-1)

    def _pad_semantic_waveform(self, waveform, *, hop_length):
        # NeuCodec's reference feeds the hop-rounded clip straight to the fbank, without XCodec2's
        # half-hop context: https://github.com/neuphonic/neucodec/blob/ed3e6cd/neucodec/model.py#L128
        return waveform

    def _pad_feature_single(self, feature, max_length, *, feature_padding_value, **kwargs):
        return self._pad_axis(feature, 0, max_length - feature.shape[0], axis=0, value=feature_padding_value)

    def _validate_preprocess_kwargs(self, *, padding_side, hop_length, stride, **kwargs):
        super()._validate_preprocess_kwargs(**kwargs)
        if padding_side != "right":
            raise ValueError("Dual-codec waveforms use right padding.")
        if hop_length <= 0 or stride <= 0:
            raise ValueError("Codec hop_length and stride must be positive.")

    def _select_semantic_waveform(self, original, acoustic, start, end, *, hop_length):
        """NeuCodec's semantic encoder remains independent of acoustic truncation."""
        valid_length = (original.shape[-1] + hop_length - 1) // hop_length * hop_length
        return self._pad_axis(original, 0, valid_length - original.shape[-1], axis=-1)

    def _preprocess(
        self,
        audio,
        *,
        padding,
        max_length,
        truncation,
        pad_to_multiple_of,
        padding_side,
        padding_value,
        return_padding_mask,
        return_tensors,
        spectrogram_config,
        hop_length,
        stride,
        feature_padding_value,
        **kwargs,
    ):
        """Assemble acoustic and semantic branches; `max_length` retains each branch's legacy units.

        Acoustic padding uses samples, semantic padding uses frames. The semantic mask is
        required by the model; `return_padding_mask` controls the optional acoustic mask.
        """
        padded, audio_ranges = self.pad(
            audio,
            padding,
            max_length,
            truncation,
            pad_to_multiple_of,
            padding_side=padding_side,
            padding_value=padding_value,
        )
        audio_values = self._stack_waveforms(padded)
        output = {"audio_values": audio_values}
        if return_padding_mask:
            output["audio_values_mask"] = self._get_mask(audio_ranges, audio_values.shape[-1])

        features = []
        for i, (start, end) in enumerate(audio_ranges):
            waveform = self._select_semantic_waveform(audio[i], audio_values[i], start, end, hop_length=hop_length)
            waveform = self._pad_semantic_waveform(waveform, hop_length=hop_length)
            features.append(
                self._standardize_frames(
                    self.compute_features([waveform], spectrogram_config=spectrogram_config, **kwargs)[0]
                )
            )

        features, frame_ranges = self._pad_features(
            features,
            padding,
            max_length,
            truncation,
            stride,
            padding_value=padding_value,
            feature_padding_value=feature_padding_value,
            **kwargs,
        )
        batch = self._stack(features)
        mask = self._get_mask(frame_ranges, batch.shape[1])

        batch_size, num_frames, num_mel_bins = batch.shape
        output["audio_features"] = batch.reshape(batch_size, num_frames // stride, num_mel_bins * stride)
        stride_groups = mask.reshape(batch_size, num_frames // stride, stride)
        output["audio_features_mask"] = _array_namespace(mask).amin(stride_groups, -1)
        return BatchFeature(output, tensor_type=return_tensors)


class NeuCodecAudioProcessor(NeuCodecAudioProcessorMixin, TorchAudioBackend):
    def _standardize_frames(self, features):
        return (features - features.mean(0)) / torch.sqrt(features.var(0, unbiased=True) + 1e-7)


__all__ = ["NeuCodecAudioProcessor"]
